'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const a = new Float64Array(n);

for (let i = 0; i < n; i++) {
  a[i] = nextInt();
}

let left = 0;
let right = n - 1;
let operations = 0;

while (left < right) {
  if (a[left] === a[right]) {
    left++;
    right--;
  } else if (a[left] < a[right]) {
    a[left + 1] += a[left];
    left++;
    operations++;
  } else {
    a[right - 1] += a[right];
    right--;
    operations++;
  }
}

